<?php $title = 'Produkty | ShopStack'; require __DIR__ . '/../layouts/header.php'; ?><div class="section-head"><div><p class="eyebrow">KATALOG</p><h1>Wszystkie produkty</h1></div></div><form class="filters" method="get"><input name="q" placeholder="Szukaj produktów" value="<?= e($query) ?>"><select name="category"><option value="0">Wszystkie kategorie</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= $selectedCategory === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><select name="sort"><option value="newest">Najnowsze</option><option value="price_asc" <?= $sort === 'price_asc' ? 'selected' : '' ?>>Cena rosnąco</option><option value="price_desc" <?= $sort === 'price_desc' ? 'selected' : '' ?>>Cena malejąco</option><option value="name" <?= $sort === 'name' ? 'selected' : '' ?>>Nazwa</option></select><button class="button">Filtruj</button></form><div class="product-grid"><?php foreach ($products as $product): ?><article class="product-card"><div class="product-image"><?= e(strtoupper(substr($product['name'], 0, 1))) ?></div><p class="eyebrow"><?= e($product['category_name']) ?></p><h3><?= e($product['name']) ?></h3><p><?= e(mb_strimwidth($product['description'], 0, 90, '...')) ?></p><strong><?= money($product['price']) ?></strong><a class="stretched" href="<?= e($config['url']) ?>/products/<?= e($product['id']) ?>">Zobacz produkt</a></article><?php endforeach; ?></div><?php require __DIR__ . '/../layouts/footer.php'; ?>
